archivosIniciales.app.js:
const estado = { tareas: [] };
const formulario = document.getElementById("formulario");
const entrada = document.getElementById("nueva-tarea");
const lista = document.getElementById("lista");
const contador = document.getElementById("contador");

function dibujar() {
  lista.textContent = "";
  estado.tareas.forEach((tarea, indice) => {
    const item = document.createElement("li");
    item.textContent = tarea.texto;
    if (tarea.hecha) item.classList.add("hecha");
    item.addEventListener("click", () => {
      estado.tareas = completarTarea(estado.tareas, indice);
      dibujar();
    });
    lista.appendChild(item);
  });
  contador.textContent = `${pendientes(estado.tareas)} pendientes`;
}

formulario.addEventListener("submit", (evento) => {
  evento.preventDefault();
  estado.tareas = agregarTarea(estado.tareas, entrada.value);
  entrada.value = "";
  dibujar();
});

dibujar();

